insert into public.antibiotic_interactions (drug_id, with_ar, with_en, desc_ar, desc_en, severity, source_ids, sort, reviewed, deleted) values ('orita', $q$الهيبارين غير المجزأ وريدياً$q$, $q$Intravenous unfractionated heparin$q$, $q$ممنوع 120 ساعة (5 أيام) بعد الجرعة: يطيل فحص aPTT كاذباً.$q$, $q$Contraindicated for 120 hours (5 days) after the dose: falsely prolongs aPTT.$q$, 'major', '{108}', 10, false, false);
insert into public.antibiotic_interactions (drug_id, with_ar, with_en, desc_ar, desc_en, severity, source_ids, sort, reviewed, deleted) values ('orita', $q$الوارفارين$q$, $q$Warfarin$q$, $q$يطيل PT/INR كاذباً حتى 12 ساعة؛ مراقبة النزف.$q$, $q$Falsely prolongs PT/INR for up to 12 hours; watch for bleeding.$q$, 'moderate', '{108}', 20, false, false);
insert into public.antibiotic_interactions (drug_id, with_ar, with_en, desc_ar, desc_en, severity, source_ids, sort, reviewed, deleted) values ('orita', $q$أدوية ذات هامش علاجي ضيق تُستقلب بـ CYP2C9 أو 2C19 أو 3A4 أو 2D6$q$, $q$Narrow-margin drugs metabolised by CYP2C9, 2C19, 3A4 or 2D6$q$, $q$قد ترتفع أو تنخفض: يُتجنب أو مراقبة.$q$, $q$They may rise or fall: avoid or monitor.$q$, 'moderate', '{108}', 30, false, false);
